// Food photos illustrate recipe categories, not the exact prepared recipe.
// Selection is stable per recipe ID and is only varied inside a suitable group.
const ORIGINAL_KEYS = new Set(['bowl','chicken','salmon','pasta','salad','soup','pancakes','oats','toast','dessert','rice','potato','omelet','beef','smoothie']);
const normalize = value => String(value || '').toLowerCase().replaceAll('ё', 'е');
const stableIndex = (id, count) => {
  let value = 2166136261;
  for (const c of String(id || 'recipe')) value = Math.imul(value ^ c.charCodeAt(0), 16777619);
  return (value >>> 0) % count;
};
export function recipePhoto(recipe) {
  const r = recipe || {};
  if (r.id === 'r001') return 'assets/bowl.jpg';
  const title = normalize(r.title);
  const family = normalize(r.family);
  const text = `${family} ${title}`;
  const ingredients = new Set((r.ingredients || []).map(i => typeof i === 'string' ? i : i.id));
  const has = (...ids) => ids.some(id => ingredients.has(id));
  const choose = (...keys) => `assets/${keys[stableIndex(r.id || title, keys.length)]}.jpg`;

  if (/пицц/.test(text)) return choose(has('chicken', 'turkey') ? 'pizza-2' : 'pizza-1');
  if (/вафл/.test(text)) return choose('waffles');
  if (/блин|креп/.test(text) && !/блинчик.*олад/.test(text)) return choose('crepes-1', 'crepes-2');
  if (/олад|панкейк|сырник/.test(text)) return choose('pancakes');
  if (/ризотто/.test(text)) return choose('risotto-1', 'risotto-2');
  if (/ролл.*лаваш|лаваш|шаурм|буррито|такос|тортиль/.test(text)) return choose(has('chicken', 'turkey') ? 'wrap-2' : 'wrap-1');
  if (/тефтел|фрикадел/.test(text)) return choose(has('tomato_can', 'tomato_paste') || /томат/.test(title) ? 'meatballs-2' : 'meatballs-1');
  if (/хумус|паштет|дип/.test(text)) return choose('hummus');
  if (/чизкейк|творожн.*запеканк/.test(text)) return choose('cheesecake');
  if (/крамбл/.test(text)) return choose('crumble-1', 'crumble-2');
  if (/пирог|шарлотк|тарт/.test(text) && has('apple','pear','berries','cherry_frozen')) return choose('apple-pie');
  if (/запеченн.*фрукт|печен.*яблок|запеченн.*яблок|запеченн.*груш/.test(text) || family === 'запеченные фрукты') return choose('baked-apple');
  if (/смузи/.test(text)) return choose('smoothie');
  if (/йогурт.*десерт|парфе|панна/.test(text)) return choose('dessert');
  if (/суп|уха|борщ|рассольник|солянк|рамен|том ям|мисо/.test(text)) {
    if (/рамен|том ям|мисо/.test(text)) return choose('soup-broth-2');
    if (/гриб/.test(title) || has('mushroom') && /крем|пюре/.test(text)) return choose('soup-mushroom');
    if (/брокколи|шпинат|зелен.*горош/.test(title) && /крем|пюре/.test(text)) return choose('soup-green');
    if (/крем|пюре|тыкв|морков|томат/.test(title)) return choose('soup');
    return choose('soup-broth-1');
  }
  if (/паста|спагетти|фетучини|пенне|фарфалле|макарон|карбонара/.test(text)) {
    if (/песто|базилик/.test(title) && !/томат/.test(title)) return choose('pasta');
    if (/томат|болоньез|маринара|аррабиата/.test(title) || has('tomato_can', 'tomato_paste')) return choose('pasta-red-1', 'pasta-red-2');
    if (/слив|сыр|карбонара|гриб/.test(title) || has('cream', 'sourcream')) return choose('pasta-cream-1', 'pasta-cream-2');
    return choose('pasta');
  }
  if (/лапша|соба|вок|удон/.test(text)) return choose('noodles-1', 'noodles-2');
  if (/карри/.test(text)) return choose('curry');
  if (/рагу|гуляш|жарк|тушен/.test(text)) return choose('stew-1', 'stew-2');
  if (/запеканк|гратен|лазан/.test(text)) return choose(has('pasta') || /лазан/.test(text) ? 'casserole-1' : 'casserole-2');
  if (/тофу/.test(text)) return choose('tofu');
  if (/омлет|шакшук|фриттат|яичниц/.test(text)) return choose('omelet');
  if (/каша|овсян|порридж/.test(text)) return choose('porridge-1', 'porridge-2', 'oats');
  if (/греческ.*салат|салат.*греческ/.test(text)) return choose('salad-greek-1');
  if (/цезарь/.test(text)) return choose('salad-caesar');
  if (/салат/.test(text)) {
    if (has('chicken', 'turkey') && has('cheese', 'parmesan')) return choose('salad-caesar');
    if (has('feta', 'mozzarella') || /огур|томат|помидор/.test(title) && !has('chicken','beef','salmon','tuna')) return choose('salad-greek-1');
    return choose('salad');
  }
  if (/тост|бутерброд|брускет/.test(text)) return choose('toast');
  return `assets/${ORIGINAL_KEYS.has(r.imageKey) ? r.imageKey : 'salad'}.jpg`;
}

